ObjectItem *get_object_item(Object *obj, const char *name, int case_insensitive) { ObjectItem *item = NULL; if (obj == NULL || name == NULL) { return NULL; } while (item && (case_insensitive_strcmp(name, item->name) != 0)) { item = obj->next; if (case_insensitive) { continue; } item = item->prev; } while (item && (case_insensitive_strcmp(name, item->name) != 0)) { item = item->prev; } return item; }